#!/usr/bin/env node
import { readFileSync, writeFileSync } from "node:fs";
import { dirname, resolve } from "node:path";
import { fileURLToPath } from "node:url";

const browser = process.argv[2];
const deviceByBrowser = {
  chromium: "Desktop Chrome",
  firefox: "Desktop Firefox",
  webkit: "Desktop Safari",
};

const device = deviceByBrowser[browser];
if (!device) {
  console.error(`Unsupported nightly browser: ${browser}`);
  process.exit(2);
}

const repoRoot = resolve(dirname(fileURLToPath(import.meta.url)), "../..");
const configPath = resolve(repoRoot, "web/playwright.config.ts");
const outputPath = resolve(repoRoot, "web/playwright.nightly.config.ts");
const source = readFileSync(configPath, "utf8");
const generated = source.replaceAll('devices["Desktop Chrome"]', `devices["${device}"]`);

writeFileSync(
  outputPath,
  `// Generated by .github/scripts/write-nightly-playwright-config.mjs; do not commit.\n${generated}`,
);
console.log(`wrote ${outputPath} using ${device}`);
